//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Values below 1 are
    /// treated as one attempt by `run_job`.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds. A zero value disables
    /// waiting between attempts.
    pub max_delay_ms: u64,
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // `max_attempts` includes the initial call. Keep zero from skipping it.
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < max_attempts => {
                sleeper.sleep_ms(delay);
                delay = delay.saturating_mul(2).min(config.max_delay_ms);
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = config(5, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_are_returned_without_retrying() {
        let config = config(4, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn zero_attempt_budget_still_makes_the_first_call() {
        let config = config(0, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn delay_overflow_still_saturates_at_the_configured_limit() {
        let config = config(3, u64::MAX, u64::MAX);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls == 3 {
                Ok(())
            } else {
                Err(RetryError::Transient("temporary".into()))
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(sleeper.sleeps, vec![u64::MAX, u64::MAX]);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` retries only `RetryError::Transient` failures. A
`RetryError::Permanent` failure is returned immediately. `max_attempts` is the
total number of job calls, including the first call; a value of zero still
allows the first call.

Before each retry, the runner asks the supplied `Sleeper` to wait. The first
wait is `base_delay_ms`, capped at `max_delay_ms`, and each subsequent wait
doubles until it reaches that cap. A `max_delay_ms` of zero results in retry
attempts without waiting. Inject `FakeSleeper` in tests to record delays without
actually sleeping.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 3,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();

run_job(&config, &mut sleeper, || {
    Err(RetryError::Transient("try again".into()))
});
assert_eq!(sleeper.sleeps, vec![100, 200]);
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_preserves_signature() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 9,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 4 {
            Ok(())
        } else {
            Err(RetryError::Transient("temporary".to_owned()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![5, 9, 9]);
}

#[test]
fn public_api_returns_permanent_failure_without_sleeping() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 5,
        max_delay_ms: 9,
    };
    let mut sleeper = FakeSleeper::default();

    let result = run_job(&config, &mut sleeper, || {
        Err(RetryError::Permanent("invalid job".to_owned()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".to_owned())));
    assert!(sleeper.sleeps.is_empty());
}
